        if(!portable_current(o,token))return;var context=Dict(o,"_portable_context");var host=context["host"].As<Node>();clear(host);var review=context["review"].AsGodotDictionary();label(host,"A separate editable composition and media folder will be created. Sources are copied byte-for-byte and deduplicated; embedded audio stays embedded. Clip windows, processing and original files stay intact.");label(host,Get(review,"reference_count",0).AsInt32()+" media reference(s) · "+(Get(review,"external_bytes",0).AsDouble()/1048576).ToString("F2",CultureInfo.InvariantCulture)+" MiB external · "+(Get(review,"embedded_bytes",0).AsDouble()/1048576).ToString("F2",CultureInfo.InvariantCulture)+" MiB embedded estimate");var list=new ItemList{SizeFlagsVertical=Control.SizeFlags.ExpandFill,CustomMinimumSize=new Vector2(0,140)};host.AddChild(list);foreach(var raw in Get(review,"entries",new GArray()).AsGodotArray()){var entry=raw.AsGodotDictionary();string source=Get(entry,"source",Get(entry,"path","Embedded audio")).AsString();int index=list.AddItem(source.GetFile()+" · "+(Get(entry,"bytes",0).AsDouble()/1048576).ToString("F2",CultureInfo.InvariantCulture)+" MiB");list.SetItemTooltip(index,source);}foreach(string warning in PackedStrings(Get(review,"warnings",new GArray())))label(host,warning);string error=Get(review,"error","").AsString();if(error.Length>0){label(host,error);ActionButton(host,"Close without copying",()=>close_portable_review(o,token));return;}var name=new LineEdit{Text=SafeCopyName(Document(o).Get("title").AsString()),PlaceholderText="Copy name"};host.AddChild(name);var destination=label(host,"Choose a parent folder. A unique new subfolder will be created; existing compositions are never selected for replacement.");var row=new HFlowContainer();host.AddChild(row);ActionButton(row,"Choose parent folder",()=>choose_portable_parent(o,token));var collect=ActionButton(row,"Create reviewed copy",()=>prepare_portable_copy(o,token));collect.Disabled=true;ActionButton(row,"Cancel",()=>close_portable_review(o,token));context["name"]=name;context["destination_label"]=destination;context["collect"]=collect;context["destination"]="";name.TextChanged+=_=>{if(portable_current(o,token)){Dict(o,"_portable_context")["destination"]="";collect.Disabled=true;destination.Text="Choose the parent folder again to confirm the new copy name.";}};label(host,"Changing this composition cancels the review. Adding new external media to a collected copy requires collecting a fresh copy before saving it as portable. This does not collect arbitrary project assets, Scene associations or executable resources.");
    }
    public void choose_portable_parent(Control o,long token)
    {
        if(!portable_current(o,token)||Dict(o,"_portable_context")["phase"].AsString()!="review")return;var context=Dict(o,"_portable_context");if(GodotObject.IsInstanceValid(Get(context,"picker").AsGodotObject()))return;var picker=new FileDialog{Title="Choose a parent folder for the new collected copy",Access=FileDialog.AccessEnum.Filesystem,FileMode=FileDialog.FileModeEnum.OpenDir,CurrentDir=ProjectRootDirectory()};o.AddChild(picker);context["picker"]=picker;picker.Canceled+=()=>{picker.QueueFree();if(portable_current(o,token))Dict(o,"_portable_context").Remove("picker");};picker.DirSelected+=parent=>{picker.QueueFree();if(!portable_current(o,token))return;var current=Dict(o,"_portable_context");current.Remove("picker");string name=SafeCopyName(current["name"].As<LineEdit>().Text.Trim());if(name.Length==0)name="Audio copy";string destination=parent.PathJoin(name+"-"+NewAudioId());current["destination"]=destination;current["destination_label"].As<Label>().Text="New folder: "+destination;current["collect"].As<Button>().Disabled=false;};picker.PopupCentered(new Vector2I(820,560));
