    public void open_collected_copy(Control o)
    {
        if(Session(o).Get("dirty").AsBool()||Session(o).Get("_before").VariantType!=Variant.Type.Nil){notice(o,"Save your current composition before opening a collected copy. Your unsaved work has not been replaced.");return;}if(Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool()||Recording(o).Get("active").AsBool()||Recording(o).Call("has_pending").AsBool()){notice(o,"Finish the current recording or automation pass first.");return;}var owner=Session(o);var document=Document(o);long revision=owner.Get("revision").AsInt64();var picker=new FileDialog{Title="Open collected audio composition",Access=FileDialog.AccessEnum.Filesystem,FileMode=FileDialog.FileModeEnum.OpenFile,Filters=new[]{"*.res,*.tres ; Editable audio composition"},CurrentDir=ProjectRootDirectory()};o.AddChild(picker);picker.Canceled+=picker.QueueFree;picker.FileSelected+=chosen=>{picker.QueueFree();if(!o.IsInsideTree()||!o.IsVisibleInTree()||Session(o)!=owner||Document(o)!=document||owner.Get("revision").AsInt64()!=revision||owner.Get("dirty").AsBool()||owner.Get("_before").VariantType!=Variant.Type.Nil||Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool()||Recording(o).Get("active").AsBool()||Recording(o).Call("has_pending").AsBool()){notice(o,"The active composition changed. Open the intended copy again after saving your work.");return;}o.Call("open_source",chosen);};picker.PopupCentered(new Vector2I(820,560));
